select id, 'inverters', 'Inverters', 'Inverter', 'Hybrid and commercial inverters from 5kVA to 10kVA.', 'The heart of every solar system. Africell hybrid inverters combine solar charging, battery management and grid/generator input in one wall-mounted unit, for homes, shops and commercial premises.', '/images/products/inverter-hybrid.webp', array['lithium-batteries', 'solar-panels']::text[], 0
from public.brands where slug = 'africell';
insert into public.product_series (category_id, slug, name, tagline, overview, features, applications, gallery, spec_status, spec_note, spec_layout, settings, guide, in_the_box, downloads, sort_order)
select c.id, 'premium-hybrid-inverters', 'Premium Hybrid Inverter Range', 'Residential and commercial power from 5kVA to 10kVA', array['The Africell Premium range covers the most common power needs in Nigerian homes and businesses: 5kVA for households and small offices, and 7.5kVA and 10kVA for larger homes, shops and commercial premises.', 'Hybrid operation means one unit manages your solar panels, your battery bank and grid or generator input, switching automatically so your power stays on.']::text[], '[{"title":"Built-in MPPT solar charging","text":"An integrated MPPT charge controller harvests the maximum available energy from your solar panels."},{"title":"Parallel expansion","text":"The 5kVA model supports up to 12 units in parallel, so capacity can grow with your needs."},{"title":"Hybrid operation","text":"Works with solar, battery and grid or generator input, prioritising solar to cut fuel and electricity costs."},{"title":"Wall-mounted design","text":"A clean, compact cabinet with an LCD display for at-a-glance status."}]'::jsonb, array['Homes and apartments', 'Shops and offices', 'Schools, clinics and churches', 'Commercial premises']::text[], array['/images/products/inverter-hybrid.webp']::text[], 'pending', 'Full electrical datasheets for this range are being confirmed with the manufacturer. Ask our team for the complete specification before you buy.', '[{"title":"Overview","rows":[{"label":"Rated power"},{"label":"Type"},{"label":"Intended use"},{"label":"Solar charge controller"},{"label":"Parallel operation"}]},{"title":"Electrical","rows":[{"label":"Battery voltage","shared":null},{"label":"Max. PV input voltage","shared":null},{"label":"Max. solar charging current","shared":null},{"label":"Output waveform","shared":null}]}]'::jsonb, null, '[]'::jsonb, '{}'::text[], '[]'::jsonb, 0
from public.categories c join public.brands b on b.id = c.brand_id
where b.slug = 'africell' and c.slug = 'inverters';
