select id, 'lithium-batteries', 'Lithium Batteries', 'Lithium Battery', '51.2V LiFePO4 storage from 5.12kWh to 15.36kWh.', 'Long-life lithium iron phosphate (LiFePO4) energy storage with built-in battery management. Store daytime solar for night-time use, and expand capacity by connecting packs in parallel.', '/images/products/hy-300-main.webp', array['inverters', 'solar-panels']::text[], 1
