insert into public.product_series (category_id, slug, name, tagline, overview, features, applications, gallery, spec_status, spec_note, spec_layout, settings, guide, in_the_box, downloads, sort_order)
select c.id, 'hy-series', 'HY Series LiFePO4 Battery', '51.2V household energy storage, 5.12kWh to 15.36kWh', array['The HY Series is a 51.2V lithium iron phosphate battery system designed for household solar installations. Four capacities let you match storage to your evening and overnight load.', 'A built-in battery management system (BMS) monitors every pack and keeps it within safe operating limits. Packs communicate with compatible inverters over CAN and RS485, and up to 16 can be connected in parallel as your needs grow.']::text[], '[{"title":"LiFePO4 chemistry","text":"Lithium iron phosphate cells offer high thermal stability and a rated cycle life of at least 6,000 cycles at 80% depth of discharge."},{"title":"Built-in BMS","text":"The battery management system monitors operation and prevents the pack from working outside its design limits."},{"title":"Expandable to 16 packs","text":"Add capacity later by connecting additional packs in parallel through a matching junction box."},{"title":"Inverter communication","text":"CAN and RS485 ports let the battery report its status directly to compatible inverters."},{"title":"Deep usable capacity","text":"Depth of discharge of 95% or more means more of the rated energy is available to you."},{"title":"Made for home solar","text":"Compact, high-energy-density design intended for residential PV systems."}]'::jsonb, array['Overnight home backup', 'Solar self-consumption', 'Shops and small offices', 'Reducing generator run time']::text[], array['/images/products/hy-300-main.webp', '/images/products/hy-200-main.webp', '/images/products/hy-wall-main.webp', '/images/products/hy-wall-ports.webp', '/images/products/hy-300-overview.webp']::text[], 'verified', 'Specifications as published by the manufacturer. Confirm the exact model with our team before purchase.', '[{"title":"Electrical","rows":[{"label":"Usable capacity"},{"label":"Nominal voltage","shared":"51.2 V"},{"label":"Voltage range","shared":"40 – 58.4 V"},{"label":"Recommended charge cut-off voltage","shared":"58.4 V"},{"label":"Recommended discharge cut-off voltage","shared":"40.0 V"},{"label":"Max. charge current"},{"label":"Max. discharge current"},{"label":"Recommended charge / discharge current"},{"label":"Depth of discharge (DOD)","shared":"≥ 95%"},{"label":"Cycle life","shared":"≥ 6,000 cycles @ 25°C, 80% DOD"}]},{"title":"System","rows":[{"label":"Parallel connection","shared":"1 – 16 packs"},{"label":"Communication","shared":"CAN & RS485"},{"label":"Ingress protection","shared":"IP21"}]},{"title":"Environmental","rows":[{"label":"Operating temperature (discharge)","shared":"−20°C to +60°C"},{"label":"Operating temperature (charge)","shared":"0°C to +55°C"}]},{"title":"Mechanical","rows":[{"label":"Dimensions (mm)"},{"label":"Package dimensions (mm)"},{"label":"Net weight"},{"label":"Gross weight"}]}]'::jsonb, '{"title":"Recommended inverter / charger settings","rows":[{"label":"Max. charging voltage","shared":"58.4 V"},{"label":"Float charging voltage","shared":"57.6 V"},{"label":"Max. charging current","shared":"50 A × N (N = number of packs in parallel)"},{"label":"Cut-off voltage","shared":"40.0 V"}]}'::jsonb, '[{"title":"Before installation","paragraphs":["Inspect the unit on delivery and make sure nothing in the package is damaged. Lithium batteries are not the same as lead-acid batteries, so any inverter, MPPT charge controller or UPS connected to the pack must be configured with the recommended settings above before it is switched on."]},{"title":"Connecting to the inverter","steps":["Fix the mounting bracket to the battery, mark its position on the wall and install the expansion screws.","Connect the battery''s positive and negative terminals to the inverter''s positive and negative battery terminals.","Connect the communication cable according to your inverter''s instructions (CAN or RS485).","For multiple packs in parallel, use a matching junction box."],"image":"/images/products/hy-wiring.webp"},{"title":"Switching on and the reset button","paragraphs":["Turn the battery on with its low-voltage switch. The reset button has several functions: a 3–6 second press wakes the BMS from sleep or puts it to sleep; a 6–10 second press resets the protection board; three presses within 5 seconds re-codes the BMS address."]},{"title":"Sleep and wake-up","paragraphs":["The BMS enters sleep mode if under-voltage protection is not cleared within 30 seconds, if the button is pressed for 3–6 seconds, or after a period with no communication, current or protection activity. It wakes when a charger above 48V is connected, when the button is pressed, or when activated over RS485/CAN. After under-voltage protection it wakes every 4 hours to attempt charging."]}]'::jsonb, array['Battery pack', 'Parallel connection cables', 'Communication cable', 'Mounting screws', 'User manual', 'Guarantee card']::text[], '[]'::jsonb, 0
from public.categories c join public.brands b on b.id = c.brand_id
where b.slug = 'africell' and c.slug = 'lithium-batteries';
