insert into public.product_series (category_id, slug, name, tagline, overview, features, applications, gallery, spec_status, spec_note, spec_layout, settings, guide, in_the_box, downloads, sort_order)
select c.id, 'gl-mono-series', 'GL-MONO Monocrystalline Solar Panels', 'From 180W to 650W, for homes, businesses and solar plants', array['GL-MONO modules use monocrystalline silicon cells for strong conversion efficiency in a durable aluminium-framed panel. Ten power ratings let you size an array precisely for your roof space and energy needs.']::text[], '[{"title":"Monocrystalline cells","text":"High conversion efficiency for more energy per square metre of roof."},{"title":"Low light-induced degradation","text":"Designed for stable output over a long service life."},{"title":"Built for tough conditions","text":"Rated by the manufacturer to withstand high wind pressure and extreme temperatures."},{"title":"Weather-sealed junction box","text":"Sealed junction box and pre-fitted output cables for straightforward installation."}]'::jsonb, array['Residential rooftops', 'Commercial and industrial rooftops', 'Off-grid systems', 'Solar power plants']::text[], array['/images/products/panel-front.webp', '/images/products/panel-pair.webp', '/images/products/panel-detail.webp', '/images/products/panel-connectors.webp']::text[], 'partial', 'The source datasheet listed identical electrical and mechanical values for every wattage, which cannot be correct. We are confirming per-model figures with the manufacturer and only show verified values here.', '[{"title":"Electrical (STC)","rows":[{"label":"Peak power (Pmax)"},{"label":"Cell type","shared":"Monocrystalline"},{"label":"Max. power voltage (Vmp)","shared":null},{"label":"Max. power current (Imp)","shared":null},{"label":"Open-circuit voltage (Voc)","shared":null},{"label":"Module efficiency","shared":null}]},{"title":"Mechanical","rows":[{"label":"Frame","shared":"Anodised aluminium alloy"},{"label":"Front glass","shared":"High-transmission, low-iron tempered glass"},{"label":"Dimensions","shared":null},{"label":"Weight","shared":null}]}]'::jsonb, null, '[]'::jsonb, '{}'::text[], '[]'::jsonb, 0
from public.categories c join public.brands b on b.id = c.brand_id
where b.slug = 'africell' and c.slug = 'solar-panels';
insert into public.products (series_id, slug, name, model, chips, power_kva, capacity_kwh, wattage, image, gallery, summary, spec_values, availability, sort_order)
select s.id, 'gl-mono-' || w || 'w', w || 'W Monocrystalline Solar Panel', 'GL-MONO-' || w || 'W', array[w || ' W', 'Monocrystalline']::text[], null, null, w,
  case when w >= 400 then '/images/products/panel-front.webp' else '/images/products/panel-classic.webp' end,
  case when w >= 400 then array['/images/products/panel-front.webp', '/images/products/panel-pair.webp', '/images/products/panel-detail.webp', '/images/products/panel-connectors.webp']::text[]
       else array['/images/products/panel-classic.webp', '/images/products/panel-detail.webp', '/images/products/panel-connectors.webp']::text[] end,
  case when w >= 500 then 'A high-output ' || w || 'W monocrystalline module for large rooftops, commercial arrays and solar plants.'
       when w >= 400 then 'A ' || w || 'W monocrystalline module that balances output and roof space for home and business systems.'
       else 'A ' || w || 'W monocrystalline module for smaller systems, limited roof space and off-grid applications.' end,
  jsonb_build_object('Peak power (Pmax)', w || ' W'), 'enquire', ord - 1
from public.product_series s join public.categories c on c.id = s.category_id,
  unnest(array[180, 300, 330, 350, 400, 430, 480, 550, 600, 650]) with ordinality as t(w, ord)
where c.slug = 'solar-panels' and s.slug = 'gl-mono-series';

